// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.skill/** * NOUS — System operations. * * Side-effectful actions on Android that rules and skills can trigger. * Each operation is a sealed variant with typed parameters. * * Actual execution is performed by [SystemOperationExecutor] which wraps * Android system services (CameraManager, AudioManager, WindowManager, etc.). * * @see <a href="docs/spec/module2-spec-review.pdf">§3.2 SystemOperation</a> */sealed interface SystemOperation {    // ─── Torch ────────────────────────────────────────────────────────────    data class SetTorch(val on: Boolean, val brightness: Float = 1.0f) : SystemOperation    // ─── Volume ───────────────────────────────────────────────────────────    data class AdjustVolume(val delta: Int, val stream: AudioStream = AudioStream.MEDIA) : SystemOperation    data class SetVolume(val level: Int, val stream: AudioStream = AudioStream.MEDIA) : SystemOperation    // ─── Display ──────────────────────────────────────────────────────────    data class SetDisplayBrightness(val level: Float) : SystemOperation  // 0.0 - 1.0    /** Adjust display brightness by a delta (e.g., +0.1, -0.1). Used by BrightnessUp/Down rules. */    data class AdjustDisplayBrightness(val delta: Float) : SystemOperation    /** Turn the screen on (wake). */    data object ScreenOn : SystemOperation    /** Lock the screen (alias of LockScreen below for clarity). */    data object ScreenOff : SystemOperation    // ─── Ringer ───────────────────────────────────────────────────────────    data class SetRingerMode(val mode: RingerMode) : SystemOperation    // ─── Connectivity ─────────────────────────────────────────────────────    data class SetAirplaneMode(val on: Boolean) : SystemOperation    data class SetWifi(val on: Boolean) : SystemOperation    data class SetBluetooth(val on: Boolean) : SystemOperation    // ─── Apps ─────────────────────────────────────────────────────────────    data class OpenApp(val packageName: String, val appName: String? = null) : SystemOperation    data class OpenUrl(val url: String) : SystemOperation    // ─── Clipboard ────────────────────────────────────────────────────────    data class CopyToClipboard(val text: String) : SystemOperation    // ─── Time / Alarms ────────────────────────────────────────────────────    data class SetAlarm(val hour: Int, val minute: Int, val label: String? = null) : SystemOperation    data class SetTimer(val durationSeconds: Long, val label: String? = null) : SystemOperation    // ─── Communications ───────────────────────────────────────────────────    data class SendSms(val contact: String, val message: String) : SystemOperation    data class MakeCall(val contact: String) : SystemOperation    // ─── Extended connectivity (Module 10 v2 — Review 1) ───────────────────    /** Set location mode (GPS). Requires WRITE_SECURE_SETTINGS for direct toggle;     *  falls back to opening Location Settings page on regular apps. */    data class SetLocationMode(val mode: LocationMode) : SystemOperation    /** Toggle Wi-Fi hotspot / tethering. Requires CHANGE_NETWORK_STATE. */    data class SetTethering(val enabled: Boolean) : SystemOperation    /** Toggle NFC. Requires WRITE_SECURE_SETTINGS for direct toggle;     *  falls back to opening NFC Settings page. */    data class SetNfc(val enabled: Boolean) : SystemOperation    // ─── Display (Module 10 v2 additions) ──────────────────────────────────    /** Lock the screen (biometric-friendly via AccessibilityService).     *  NOT DevicePolicyManager.lockNow — that breaks biometric unlock. */    data object LockScreen : SystemOperation    /** Toggle "keep screen on" flag for the current window. */    data class SetKeepScreenOn(val enabled: Boolean) : SystemOperation    // ─── Notifications / DnD / Battery (Module 10 v2 additions) ────────────    /** Set Do Not Disturb mode. Requires ACCESS_NOTIFICATION_POLICY. */    data class SetDndMode(val mode: DndMode) : SystemOperation    /** Toggle Battery Saver mode. */    data class SetBatterySaver(val enabled: Boolean) : SystemOperation    /**     * Post a notification to the system notification tray.     *     * Used by the proactive engine (Module 16) and Brain skills (Module 2)     * to surface alerts/reminders/suggestions to the user. Undo cancels the     * notification by ID via [NotificationHandler].     *     * @param id           notification ID (use for cancel/replace).     * @param channelId    NotificationManager channel ID (auto-created).     * @param channelName  user-visible channel name (e.g., "NOUS Proactive").     * @param title        notification title.     * @param text         notification body.     */    data class PostNotification(        val id: Int,        val channelId: String,        val channelName: String,        val title: String,        val text: String,    ) : SystemOperation    // ─── Composite ────────────────────────────────────────────────────────    /** Execute multiple operations in sequence. */    data class Composite(val operations: List<SystemOperation>) : SystemOperation}/** Android audio streams. */enum class AudioStream {    MEDIA,    RING,    NOTIFICATION,    ALARM,    CALL,    SYSTEM,}/** Ringer modes. */enum class RingerMode {    NORMAL,    VIBRATE,    SILENT,}/** Location accuracy modes (Module 10 v2 — Review 1). */enum class LocationMode {    HIGH_ACCURACY,    BATTERY_SAVING,    SENSORS_ONLY,    OFF,}/** Do Not Disturb modes (Module 10 v2). */enum class DndMode {    /** All notifications suppressed. */    NONE,    /** Only priority interruptions allowed. */    PRIORITY,    /** Only alarms allowed. */    ALARMS,    /** All notifications allowed (DnD off). */    ALL,}